-- Algeria service areas.
--
-- Four regions are defined here. Which of them the backend actually serves is
-- decided separately, by the merchant's origin/destination restriction, which
-- setup.sh sets from the COVERAGE variable:
--
--   COVERAGE=nationwide   ->  {Algeria}                   (default)
--   COVERAGE=cities       ->  {Algiers, Oran, Annaba}
--
-- Both are one UPDATE apart, so switching is instant and needs no rebuild.
-- Loading all four rows regardless keeps that switch free.
--
-- How serviceability works
-- (rider-app Main/src/Storage/Queries/Geometry.hs, someGeometriesContain):
--
--     SELECT * FROM atlas_app.geometry
--      WHERE region IN (<merchant.origin_restriction>)
--        AND ST_Contains(geom, ST_Point(lon, lat));
--
-- So a service area is data, not code: a row here plus its name in the
-- restriction array. NULL restriction means Unrestricted -- the whole world,
-- no geofence at all -- which is why nationwide uses a real border instead.
--
-- Boundaries: OpenStreetMap, simplified with ST_SimplifyPreserveTopology to
-- keep this file reviewable.
--   Algeria  relation 192756   admin_level=2   ~200 m   12109 -> 1533 pts
--   Algiers  relation 157062   admin_level=4    ~55 m   13215 ->  655 pts
--   Oran     relation 1259187  admin_level=4    ~55 m    7737 -> 1152 pts
--   Annaba   relation 1455599  admin_level=4    ~55 m   12047 ->  778 pts
--   (c) OpenStreetMap contributors, ODbL.
--
-- Verified against the national boundary: Algiers, Oran, Annaba, Constantine,
-- Setif, Batna, Bechar, Tamanrasset, Adrar, Tlemcen and Ghardaia are all
-- inside; Tunis, Oujda (Morocco) and Bangalore are outside.
--
-- SRID is 0, not 4326, to match the existing rows and the ST_Point() the
-- application builds -- PostGIS refuses ST_Contains across mismatched SRIDs.
--
-- Idempotent: safe to re-run.
--
-- NOTE: the merchant row is cached in Redis
-- (Main/src/Storage/CachedQueries/Merchant.hs). After changing coverage the
-- cache must be dropped or the API keeps serving the previous areas:
--     docker exec ny-redis redis-cli FLUSHALL
-- setup.sh does this automatically.

BEGIN;

DELETE FROM atlas_app.geometry WHERE region IN ('Algeria', 'Algiers', 'Oran', 'Annaba');

INSERT INTO atlas_app.geometry (id, region, geom) VALUES
